mapper.select:
select wsd.*, wc.name as waste_classification_name, wc.measure_unit from wms_waste_sale_detail as wsd left join wms_waste_classification as wc on wsd.waste_classification_id = wc.id where wsd.bool_delete_enum = 0
AND wsd.waste_sale_id in
#{wasteSaleId}

select wsd.id, wsd.waste_sale_id, wsd.sale_mete, wsd.price, wsd.amount, wsd.remark, wsd.waste_classification_id, wc.name as waste_classification_name, wsd.create_time, wc.measure_unit, ws.contract_waste_id, cw.serial_number, cw.purchaser, ws.sale_date, ws.branch_company_id, bc.name as branch_company_name, ws.plate_number, ws.create_user_id, u1.name as create_user_name, ws.audit_user_id, u2.name as audit_user_name, ws.audit_time from wms_waste_sale as ws inner join wms_waste_sale_detail as wsd on ws.id = wsd.waste_sale_id left join contract_waste as cw on ws.contract_waste_id = cw.id left join sys_branch_company as bc on ws.branch_company_id = bc.id left join wms_waste_classification as wc on wsd.waste_classification_id = wc.id left join sys_user as u1 on ws.create_user_id = u1.id left join sys_user as u2 on ws.audit_user_id = u2.id where ws.bool_delete_enum = 0 and wsd.bool_delete_enum = 0
AND DATE(ws.sale_date) >= DATE(#{startDate})
AND DATE(ws.sale_date) <= DATE(#{endDate})
AND ws.contract_waste_id = #{contractWasteId}
AND ws.branch_company_id = #{branchCompanyId}
AND wsd.waste_classification_id = #{wasteClassificationId}
and ws.audit_status_enum = #{auditStatusEnum}
and cw.purchaser like concat('%',#{purchaser},'%')
and u1.name like concat('%',#{createUserName},'%')
and u2.name like concat('%',#{auditUserName},'%')
group by wsd.id order by ws.sale_date desc, wsd.id
